UT='/home/user/Shopify/rapporter/shopify-original-2026-11-05/atervaktivering-400/'
k=api.ShopifyKlient()
Q='query($ids:[ID!]!){nodes(ids:$ids){... on Product{id title status tags handle totalInventory mediaCount{count} variants(first:5){nodes{price}} events(first:12,reverse:true){nodes{message appTitle}}}}}'
live=[]
for a in range(0,len(IDS),20):
    live+=k.graphql(Q,{'ids':['gid://shopify/Product/'+i for i in IDS[a:a+20]]})['nodes']
ok=[];skip=[]
for n in live:
    i=n['id'].split('/')[-1]
    why=None
    if n['status']!='ARCHIVED': why='ej arkiverad ('+n['status']+')'
    elif 'sammanslagen' in [t.lower() for t in n['tags']] or 'sync-skydd' in n['tags']: why='tagg sammanslagen/sync-skydd'
    elif n['mediaCount']['count']<1: why='inga bilder'
    elif not any(float(v['price'])>0 for v in n['variants']['nodes']): why='pris 0'
    else:
        arch=[e for e in n['events']['nodes'] if 'changed product status' in (e.get('message') or '') and 'archived' in (e.get('message') or '')]
        if not arch or arch[0].get('appTitle')!='Velomarket3': why='arkiverades inte av Velomarket3'
    (skip.append((i,why,n['title'][:50])) if why else ok.append(n))
json.dump(live,open(UT+'fore.json','w'),ensure_ascii=False,indent=1)
print('kontrollerade',len(live),'att återaktivera',len(ok),'hoppas över',len(skip))
for s in skip: print(' skip',s)
if '--kor' not in sys.argv: sys.exit(0)
done=[];fel=[]
for b in range(0,len(ok),25):
    for n in ok[b:b+25]:
        r=k.graphql('mutation($i:ProductUpdateInput!){productUpdate(product:$i){product{id status} userErrors{message}}}',{'i':{'id':n['id'],'status':'ACTIVE'}})
        e=r['productUpdate']['userErrors']
        (fel.append((n['id'],e)) if e else done.append(n['id']))
    chk=k.graphql(Q,{'ids':[n['id'] for n in ok[b:b+25]]})['nodes']
    bad=[c['id'] for c,n in zip(chk,ok[b:b+25]) if c['status']!='ACTIVE' or c['handle']!=n['handle'] or c['totalInventory']!=n['totalInventory'] or set(c['tags'])!=set(n['tags'])]
    print('omgång',b//25+1,'klar, avvikelser:',len(bad))
    if bad or fel: print('STOPP',bad,fel); break
    time.sleep(1)
json.dump({'aktiverade':done,'fel':fel,'hoppade':skip},open(UT+'resultat.json','w'),indent=1)
print('återaktiverade',len(done),'fel',len(fel))
